
module BFAdd16(
  input         clock,
  input  [15:0] io_a,
  input  [15:0] io_b,
  input         io_sub,
  output [15:0] io_result
);

BF16AddIP BF16AddIP_inst (
  //.alck(clock),                                        // input wire aclk
  .s_axis_a_tvalid(1'b1),                  // input wire s_axis_a_tvalid
  //.s_axis_a_tready(),                  // output wire s_axis_a_tready
  .s_axis_a_tdata(io_a),                    // input wire [15 : 0] s_axis_a_tdata
  .s_axis_b_tvalid(1'b1),                  // input wire s_axis_b_tvalid
  //.s_axis_b_tready(),                  // output wire s_axis_b_tready
  .s_axis_b_tdata(io_b),                    // input wire [15 : 0] s_axis_b_tdata
  .s_axis_operation_tvalid(1'b1),  // input wire s_axis_operation_tvalid
  //.s_axis_operation_tready(),  // output wire s_axis_operation_tready
  .s_axis_operation_tdata({7'b0, io_sub}),    // input wire [7 : 0] s_axis_operation_tdata
  .m_axis_result_tvalid(),        // output wire m_axis_result_tvalid
  .m_axis_result_tdata(io_result)          // output wire [15 : 0] m_axis_result_tdata
);
endmodule
